import{z as l,x as s,o as B,c as i,q as A,j as r,D as a,d as t,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"KV 抽象的对照","description":"","frontmatter":{"title":"KV 抽象的对照","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-kv-abstraction-comparison.md","filePath":"llm/fw-kv-abstraction-comparison.md","lastUpdated":1791063341000}'),C={name:"llm/fw-kv-abstraction-comparison.md"};function p(D,E,m,d,c,f){const e=s("Mermaid");return B(),i("div",null,[E[2]||(E[2]=A('<h1 id="kv-抽象的对照" tabindex="-1">KV 抽象的对照 <a class="header-anchor" href="#kv-抽象的对照" aria-label="Permalink to &quot;KV 抽象的对照&quot;">​</a></h1><div class="epigraph"><p>键值张量本身没有分歧，分歧全在账本：逻辑到物理的映射握在谁手里，共享与回收就在谁那里成为可能或不可能。</p><footer>—— 据 Kwon 等，SOSP 2023；SGLang 前缀树文档；Transformers 缓存对象文档，按各仓库源码整理</footer></div><p><a href="/llm/fw-kernel-interface-comparison">上一课</a>对照了注意力插座，本课对照插座底下那本账：KV 的数据结构。机制面已各有课：生命周期与所有权、分页与碎片、前缀共享的簿记，见 KV 课序的 <a href="/llm/kv-lifecycle-ownership">生命周期</a>、<a href="/llm/kv-paging-fragmentation">分页与碎片</a>、<a href="/llm/kv-prefix-cache">前缀缓存</a>，页表与引用计数的出处见 <a href="/llm/paged-attention">PagedAttention</a>。本课把六家走读对象的 KV 抽象并排，以各仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>并排时会发现一个反差：张量布局大同小异——逐层、逐头的键值矩阵——可跨请求共享、序列分叉、跨卡迁移这些能力，六家高度参差。能力差异不来自张量，来自<strong>账本</strong>：谁记录「第几个逻辑 token 在哪个物理位置」「这一页还有几条序列指着它」「树里哪段前缀可以指给新请求」。走读要回答：账本握在谁手里，决定了哪些操作是改一行索引、哪些是搬数据。</p><p><span class="marginnote">直觉类比：KV 张量是书架上的书，「账本」是图书馆的索引卡片。两个图书馆可以藏书一模一样，但一个有卡片目录（按页、按引用计数管理），就能做到「十个人同时借同一章」不用复印；另一个没有目录、整包书借出（整个会话张量绑死），第二个人只能等或复印。能力差距在目录，不在藏书。</span></p><h3 id="账本放哪" tabindex="-1">账本放哪 <a class="header-anchor" href="#账本放哪" aria-label="Permalink to &quot;账本放哪&quot;">​</a></h3><p>服务引擎把账本中央化。vLLM 用块池加每序列块表，V1 的块以内容哈希入册，相同前缀天然命中同一物理块，前缀缓存就是账本上的一次查册；抢占时记下块表、释放物理页，恢复时按账重建。SGLang 用双池加树：请求到槽位的索引池、槽位到张量的池，前缀树是第三层索引，命中即把新请求的一段槽位指向旧张量，本课不重画树的插入与淘汰。会话库把账本交还调用方。Transformers 的缓存对象族是逐层键值对的容器：动态缓存追加快，静态缓存预分配好喂编译与投机，但它只有一个会话的账，跨请求共享与回收根本不在对象接口里。llama.cpp 把账记在会话内：缓存格子上的位置与序列集合支持同会话分叉，但没有跨会话册页。编译路线里，MLC 的分页缓存是编译产物侧的不透明对象，页表操作沉进产物；TensorRT-LLM 的缓存管理器在运行库内记账，总预算在构建期算定。</p>',8)),(B(),r(o,null,{default:a(()=>[n(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KV%5B%22KV%20%E5%BC%A0%E9%87%8F%EF%BC%88%E5%B8%83%E5%B1%80%E5%90%84%E5%AE%B6%E7%9B%B8%E8%BF%91%EF%BC%89%22%5D%20--%3E%20AC%5B%22%E8%B4%A6%E6%9C%AC%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20AC%20--%3E%20A%5B%22vLLM%EF%BC%9A%E4%B8%AD%E5%A4%AE%E5%9D%97%E6%B1%A0%20%2B%20%E5%9D%97%E8%A1%A8%EF%BC%88%E5%86%85%E5%AE%B9%E5%93%88%E5%B8%8C%E5%85%A5%E5%86%8C%EF%BC%89%22%5D%0A%20%20AC%20--%3E%20B%5B%22SGLang%EF%BC%9A%E5%8F%8C%E6%B1%A0%20%2B%20%E5%89%8D%E7%BC%80%E6%A0%91%E7%B4%A2%E5%BC%95%22%5D%0A%20%20AC%20--%3E%20C%5B%22Transformers%EF%BC%9A%E4%BC%9A%E8%AF%9D%E5%86%85%E7%BC%93%E5%AD%98%E5%AF%B9%E8%B1%A1%E6%97%8F%22%5D%0A%20%20AC%20--%3E%20D%5B%22llama.cpp%EF%BC%9A%E4%BC%9A%E8%AF%9D%E5%86%85%E7%BC%93%E5%AD%98%E6%A0%BC%E5%AD%90%22%5D%0A%20%20AC%20--%3E%20E%5B%22MLC%20%2F%20TRT-LLM%EF%BC%9A%E4%BA%A7%E7%89%A9%E4%B8%8E%E8%BF%90%E8%A1%8C%E5%BA%93%E5%86%85%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20A%20--%3E%20X%5B%22%E8%B7%A8%E8%AF%B7%E6%B1%82%E5%85%B1%E4%BA%AB%E3%80%81%E6%8A%A2%E5%8D%A0%E9%87%8D%E5%BB%BA%EF%BC%9A%E6%94%B9%E7%B4%A2%E5%BC%95%22%5D%0A%20%20C%20--%3E%20Y%5B%22%E8%B7%A8%E8%AF%B7%E6%B1%82%E5%85%B1%E4%BA%AB%EF%BC%9A%E6%8E%A5%E5%8F%A3%E5%A4%96%E4%B8%8D%E5%AD%98%E5%9C%A8%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p><span class="marginnote">「内容哈希入册」是 vLLM V1 账本最值得读的一笔：块的身份由其 token 序列与父块哈希共同决定，前缀命中不需要树结构，沿块表逐块查册即可；这与 SGLang 的树是同一语义的两种索引实现，读码时不要把它们当成两种机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照仍用三问式，换成账本版：一问粒度——账的最小单位是页、槽还是整个会话张量，粒度决定碎片与共享的分辨率；二问身份——一个物理块凭什么算「同一段前缀」，指针、内容哈希还是位置掩码；三问交接——序列结束、被抢占、跨卡搬移时，账本上发生哪几笔改动。检查单走完，一个框架的容量公式与故障模式基本可以预读：粒度粗的怕碎片，账在会话内的怕长会话，账在中央的怕单点。</p><p><span class="marginnote">数字实例：一个 7B 模型（32 层、32 头、每头 128 维）每生成一个 token，KV 就要存 \\(32 \\times 32 \\times 128 \\times 2 \\times 2\\) 字节 \\(\\approx 0.5\\) MB（K 和 V 各一份、FP16 两字节）。4k 上下文的一条请求就是约 2 GB。这就是为什么「复制一份公共前缀」在 KV 上是天文数字，而「引用加一」只改一个整数。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>账本位置的机制含义沿两条线展开。<strong>共享线</strong>：共享是改索引还是搬数据，完全由「身份怎么记」决定——按位置记账，分叉要复制；按内容记账，分叉是引用加一。<strong>回收线</strong>：有中央账本，才有逐出、水位与抢占后的重建；账在会话内，回收只剩「会话结束整体释放」一种动作。这也回答了概念课留下的伏笔：为什么同样的「开了前缀缓存」，效果天差地别——开不开看开关，命中多少看账本设计。三条对照课串起来，正是框架源码的三层解剖：调度定节奏，插座定快慢，账本定生死。</p>',6)),(B(),r(o,null,{default:a(()=>[n(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E8%AF%B7%E6%B1%82%20B%20%E7%9A%84%E5%89%8D%E7%BC%80%E4%B8%8E%E8%AF%B7%E6%B1%82%20A%20%E5%AE%8C%E5%85%A8%E7%9B%B8%E5%90%8C%22%5D%20--%3E%20Q%7B%22%E5%9D%97%E8%BA%AB%E4%BB%BD%E6%80%8E%E4%B9%88%E8%AE%B0%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%8C%89%E4%BD%8D%E7%BD%AE%E8%AE%B0%E8%B4%A6%22%7C%20C1%5B%22B%20%E6%97%A0%E6%B3%95%E5%BC%95%E7%94%A8%20A%20%E7%9A%84%E7%89%A9%E7%90%86%E5%9D%97%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%8A%8A%E5%85%AC%E5%85%B1%E5%89%8D%E7%BC%80%20KV%20%E5%A4%8D%E5%88%B6%E4%B8%80%E4%BB%BD%E7%BB%99%20B%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E5%A4%9A%E8%8A%B1%E4%B8%80%E5%80%8D%E6%98%BE%E5%AD%98%E4%B8%8E%E6%8B%B7%E8%B4%9D%E6%97%B6%E9%97%B4%22%5D%0A%20%20Q%20--%3E%7C%22%E6%8C%89%E5%86%85%E5%AE%B9%E8%AE%B0%E8%B4%A6%EF%BC%88%E5%93%88%E5%B8%8C%2F%E6%A0%91%EF%BC%89%22%7C%20R1%5B%22%E7%AE%97%20B%20%E5%89%8D%E7%BC%80%E7%9A%84%E5%9D%97%E5%93%88%E5%B8%8C%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E5%86%8C%E9%87%8C%E5%B7%B2%E6%9C%89%EF%BC%9A%E6%8C%87%E5%90%91%E5%90%8C%E4%B8%80%E7%89%A9%E7%90%86%E5%9D%97%22%5D%0A%20%20R2%20--%3E%20R3%5B%22%E5%BC%95%E7%94%A8%E8%AE%A1%E6%95%B0%20%2B1%EF%BC%8C%E9%9B%B6%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20R3%20--%3E%20R4%5B%22%E5%88%86%E5%8F%89%E5%8F%AA%E4%BB%8E%E4%B8%8D%E5%90%8C%E5%A4%84%E5%BC%80%E5%A7%8B%E7%AE%97%E6%96%B0%E5%9D%97%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课对照单实例账本；跨实例的 KV 迁移、PD 分离的交接与云侧计费，在 KV 课序的 <a href="/llm/kv-distributed-migration">分布式与迁移</a> 与调度课序各有专课，不混谈。量化后的 KV 让「张量布局」也出现分歧，但那是数值课的主题，账本不因字节宽度改形。结构与对象名随版本漂移，以仓库当时状态为准。下一课离开数据结构，回答读完这些之后怎么证明改动没有变慢。</p><p><span class="marginnote">初学者容易以为「前缀缓存是个开关，开了就快」。实际上命中率取决于账本能不能认出「同一段前缀」：系统提示固定、few-shot 样例一致时命中高；每条请求时间戳或随机 ID 混进开头几个 token，哈希从第一块就不同，缓存形同虚设。开关之外，先看你的请求前缀是否逐字节稳定。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KV 的能力差异在账本不在张量：映射粒度、块身份、交接动作三问定参差。</li><li>服务引擎中央记账（vLLM 块表、SGLang 双池加树），共享与回收是索引操作；会话库（Transformers、llama.cpp）账在会话内，跨请求能力接口外不存在。</li><li>按内容哈希与按位置记账是同一语义的两种索引，决定分叉是引用还是复制。</li><li>容量公式与故障模式可由账本位置预读：粒度怕碎片、会话账怕长会话、中央账怕单点。</li><li>调度定节奏、插座定快慢、账本定生死；结构名以仓库当时状态为准。</li><li>出处：vLLM（SOSP 2023）、SGLang 与 Transformers 文档，按各仓库源码对照整理。</li></ul>',5))])}const F=l(C,[["render",p]]);export{_ as __pageData,F as default};
